// Music City: Story mode (seasons and episodes), the show's timeline of world events, label management,
// tour planner, relationship circle (label, manager, family, band, fans) and social media.
const SEASON_LEN=30,SEASONS=6,YEAR=52,EPS=[21,22,22,21,22,16];
const SEASON_NAMES=['The Queen and the Princess','Highway 65','Love and Legacy','Crash Landing','The Hardest Goodbye','Sing It Home'];
const W=(s,e)=>(s-1)*YEAR+Math.round((e-1)*(SEASON_LEN-1)/(EPS[clamp(s,1,6)-1]-1));
const seasonOf=w=>Math.floor(w/YEAR)+1, inSummer=w=>w%YEAR>=SEASON_LEN, epOf=w=>{const s=seasonOf(w);if(s>SEASONS)return EPS[5];const n=EPS[s-1];if(inSummer(w))return n;let e=1;for(let i=1;i<=n;i++)if(W(s,i)<=w)e=i;return e};
function epTitle(w){const r=seedRand('ep'+w);const a=['When','Where','Nobody','Somebody','Every','Long','Before','After','Too','Not'],b=['the Lights Go Down','You Left','Knows','Like Me','Little Thing','Way Home','the Fire','the Storm','Late','Tonight','Is Fine','We Were Young'];return a[Math.floor(r()*a.length)]+' '+b[Math.floor(r()*b.length)]}
const ownsLabel=()=>!!(S.label&&!F('sold')&&(S.label.id==='own'||(S.label.id==='highway65'&&S.char==='rayna'&&F('h65'))));
const labName=()=>S.label&&S.label.id==='highway65'?'Highway 65':(S.labName||'Your label');
const familyIds=()=>Object.keys(CHARS).filter(k=>has(k)&&family(k));
const familyAvg=()=>{const f=familyIds();return f.length?Math.round(f.reduce((a,k)=>a+R(k).a,0)/f.length):50};
function labelMult(){if(ownsLabel())return 1+((S.lab&&S.lab.promo)||0)*.06;if(S.label&&S.label.id!=='indie')return .75+(S.labelRel??50)/200;return 1}
function fanbase(){const n=(S.name.split(' ')[0]||'Fan');return S.fbName||({rayna:'the Rayniacs',juliette:'the Juliettes',deacon:'the Deacon Faithful',will:'the Lexingtons'}[S.char]||n+'\'s Rebels')}

// ---------- state init / migration ----------
function storyInit(mode){S.story={on:mode!=='free',stars:[],start:seasonSnap(),done:0};S.loyal=S.loyal??60;S.labelRel=S.labelRel??(S.char==='rayna'?35:S.char==='juliette'?55:50);S.followers=S.followers??Math.round(S.fans*.6+40);S.npcF=S.npcF||{};S.gone=S.gone||{};S.seenW=S.seenW||{};S.bandMorale=S.bandMorale??70;S.trend=S.trend||[];S.lastPost=S.lastPost||0;S.lab=S.lab||null;
 ['mama','daddy'].forEach(k=>{if(has(k)){const r=R(k);r.met=1;r.tag=k==='mama'?'Mother':'Father';if(!r.a)r.a=k==='mama'?65:45}});if(ownsLabel())ensureLab()}
function seasonSnap(){return{fans:S.fans,ones:S.stats.ones,albums:S.albums.length,tours:S.stats.tours,awards:S.awards.filter(a=>a.won).length,singles:S.songs.filter(s=>s.st==='single').length,ryman:S.stats.ryman,opry:S.stats.opry,top10:S.stats.top10}}
function ensureLab(){if(!S.lab)S.lab={rep:F('h65')?55:35,roster:[],prospects:[],promo:0,earn:0,head:null,news:[]};if(!S.lab.prospects.length)scout(true)}
(function(){const _ng=window.newGame;window.newGame=function(cfg){_ng(cfg);storyInit(UI.mode||'story');save();render()}})();
(function(){const _m=window.migrate;window.migrate=function(){_m();if(!S.story)storyInit('free');else storyInit(S.story.on?'story':'free')}})();
(function(){const _cm=window.chooseMode;window.chooseMode=function(){
 $('#app').innerHTML=`<div class="wrap notabs"><h1 class="screen-h">How do you want to play?</h1>
 <button class="newcard modepick" data-mode="story"><span class="newcard-pt">${pt('rayna','happy')}</span><span><span class="eyebrow">Recommended</span><b>Story mode</b><small>Follows the real show: six seasons (21, 22, 22, 21, 22 and 16 episodes) from October 2012 to 2018, with summer breaks you can skip. The show's storylines happen when they happened on TV: Marshall Evans and Edgehill, the crash, Highway 65, Peggy, the Exes, the plane, Rayna's goodbye. Every season has goals, a finale and a "previously on". Your choices change who lives where, who loves whom and who signs with whom.</small></span></button>
 <button class="newcard modepick alt" data-mode="free"><span class="newcard-pt">${pt('juliette','happy')}</span><span><span class="eyebrow">Sandbox</span><b>Free play</b><small>No seasons or goals, just your career, for as long as you like. The show's events still happen in the world.</small></span></button>
 <button class="ghost" id="mback">Back</button></div>`;
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{UI.mode=b.dataset.mode;_cm()});$('#mback').onclick=titleScreen}})();

