 deacon:[['Stay sober (craving under 30)',()=>S.add.dep<30],['Release a solo single',st=>S.songs.filter(s=>s.st==='single').length>st.singles],['Health 70 or better',()=>S.health>=70],['Win Rayna back (romance 60)',()=>has('rayna')&&R('rayna').r>=60||S.partner==='rayna'],['Hold your family together (family 50+)',()=>familyAvg()>=50],['One year sober',()=>!!S.ach.sober]],
