function worldEvents(silent){for(const e of WORLD){if(S.seenW[e.id]||S.week<e.at)continue;S.seenW[e.id]=1;const me=e.subj.includes(S.char);const pev=e.pev&&e.pev[S.char];
 if(me&&!pev)continue;if(e.need.some(k=>k!==S.char&&!has(k)))continue;if(e.when&&!e.when())continue;
 if(e.news&&!me)news(e.news,'big');if(e.trend)S.trend.unshift(e.trend);if(e.fx&&!me)e.fx();
 if(silent||S.week-e.at>4)continue;const ev=me?pev():(e.ev?e.ev():null);if(ev){ev.id=e.id;ev.sys=1;ev.tag=ev.tag||(S.story&&S.story.on?`S${seasonOf(S.week)} · E${epOf(S.week)}`:'Nashville');UI.queue.unshift({id:e.id,ev})}}
 S.trend=S.trend.slice(0,6)}

// ---------- label management ----------
const ACT_NAMES=['Tyler Banks','Callie Rose','The Dixon Sisters','Beau Sutton','Mae Holloway','Jasper Reid','Lainey Cole','Copper Creek','Hank Delaney','Savannah Price','Eli Mercer','June Lark','Dalton Pierce','Ivy Monroe','The Gravel Road Boys','Rosie Kincaid'];
function randLook(){const g=chance(.5)?'f':'m';return{g,skin:pick(SKINS),hair:pick(HAIRS),style:pick(g==='f'?['longwave','longstraight','curly','bob','ponytail']:['short','shaggy','messy','slick']),eyes:pick(['#4a3020','#4a7fae','#5a7040','#3a2a1a']),outfit:pick(OUTFITS),top:pick(['flannel','denim','leather','shirt','dress','tee']),hat:chance(.3)?pick(['#7a5a3a','#d1b789','#1d1d1d']):null,beard:g==='m'&&chance(.5)?ri(1,2):0,earrings:g==='f'?1:0,bg:pick(['#3a2a40','#2a3a48','#40302a','#2a3a2e'])}}
function mkAct(charId){const u='a'+(S.nextId++);if(charId){const C=CHARS[charId];const f=npcFame(charId);return{uid:u,char:charId,name:C.n,look:C.look,talent:clamp(60+f/3+ri(-5,10),40,98),fame:f,morale:60,ask:Math.round(5000+f*f*60+ri(0,5000)),single:null,hits:0,singles:0}}
 const n=pick(ACT_NAMES.filter(x=>!(S.lab&&(S.lab.roster.concat(S.lab.prospects)).some(a=>a.name===x))))||'New Act '+u;const t=ri(38,90);return{uid:u,char:null,name:n,look:randLook(),talent:t,fame:ri(3,18),morale:65,ask:Math.round(2000+t*120),single:null,hits:0,singles:0}}
function addProspect(id){ensureLab();if(S.lab.roster.concat(S.lab.prospects).some(a=>a.char===id))return;S.lab.prospects.unshift(mkAct(id))}
function removeProspect(id){if(S.lab)S.lab.prospects=S.lab.prospects.filter(a=>a.char!==id)}
function addToRoster(id){ensureLab();removeProspect(id);if(S.lab.roster.some(a=>a.char===id))return;const a=mkAct(id);a.morale=70;S.lab.roster.push(a)}
function scout(init){const L=S.lab;L.prospects=L.prospects.filter(a=>a.char).slice(0,3);const pool=['scarlett','gunnar','will','zoey','avery','layla','kevin','sadie'].filter(k=>has(k)&&!L.roster.some(a=>a.char===k)&&!L.prospects.some(a=>a.char===k));if(F('julietteFree')&&has('juliette'))pool.push('juliette');
 shuffle(pool).slice(0,init?2:ri(1,2)).forEach(k=>L.prospects.push(mkAct(k)));while(L.prospects.length<5)L.prospects.push(mkAct(null))}
function labAct(k,uid){const L=S.lab;const a=L.roster.find(x=>x.uid===uid)||L.prospects.find(x=>x.uid===uid);const o=snap();let t='';
 if(k==='promo'){L.promo=+uid;save();render();return}
 if(k==='rename'){const n=prompt('Name your label',S.labName||'');if(n&&n.trim()){S.labName=n.trim().slice(0,30);save();render()}return}
 if(k==='drop'){return confirmBox(`Drop ${a.name}?`,'They\'ll leave the label. If they\'re a friend, it will sting.',()=>{L.roster=L.roster.filter(x=>x!==a);if(a.char)FX.a(a.char,-20);L.rep-=2;log(`You dropped ${a.name} from ${labName()}.`);save();render()})}
 if(!useAP(1))return;
 if(k==='scout'){scout();t='You spent a night at writers\' rounds and showcases. New names on your list.'}
 if(k==='sign'){if(S.money<a.ask){S.ap+=(UI.lastCost||1);return toast('You can\'t afford their advance.')}const p=.35+L.rep/180+(a.char?R(a.char).a/220:0)+(a.char==='juliette'&&F('julietteFree')?.2:0);if(chance(p)){FX.m(-a.ask);L.prospects=L.prospects.filter(x=>x!==a);L.roster.push(a);if(a.char)FX.a(a.char,10);t=`${a.name} signed with ${labName()}! The advance was ${money(a.ask)}.`;news(`${a.name} signs with ${labName()}`,'big');L.news.unshift(`Signed ${a.name}`)}else{t=`${a.name} turned you down. "${pick(['We got a better offer from Edgehill.','I need a bigger label right now.','It\'s not personal.'])}"`;if(a.char)FX.a(a.char,-2)}}
 if(k==='single'){const cost=Math.round(12000*(1+a.fame/40));if(S.money<cost){S.ap+=(UI.lastCost||1);return toast(`A single costs ${money(cost)} to record and promote.`)}if(a.single&&a.single.pts>0){S.ap+=(UI.lastCost||1);return toast('They already have a single on the radio.')}FX.m(-cost);const base=Math.pow(a.talent/100,2)*125*(.33+.67*a.fame/100)*(1+L.promo*.12)*(.85+L.rep/300)*rnd(.8,1.2);a.single={title:genTitle(),base,w:0,pts:.1,peak:0};a.singles++;a.morale=clamp(a.morale+8,0,100);t=`${a.name}'s new single "${a.single.title}" is going to radio. Cost ${money(cost)}.`;news(`${labName()} releases "${a.single.title}" by ${a.name}`)}
 if(k==='meet'){a.morale=clamp(a.morale+15,0,100);if(a.char)FX.a(a.char,6);t=pick([`You took ${a.name} to lunch and listened to every worry.`,`A long talk with ${a.name} about their next record.`,`You gave ${a.name} notes on their set. They took them well.`])}
 if(k==='tour'){a.tourLeft=4;a.morale=clamp(a.morale+5,0,100);t=`${a.name} is out on a four-week club tour. They'll grow their fanbase and send money home to the label.`}
 if(k==='duet'){const s=mkSong({title:genTitle(),theme:'love',q:clamp(Math.round((S.sk.writing+a.talent)/2+ri(0,12)),30,97),prod:ri(70,88),st:'recorded',duet:a.char,co:a.char});S.songs.push(s);FX.a(a.char,8);a.fame+=3;t=`You cut "${s.title}" with ${a.name}. Release it from the Music tab.`}
 log(t);result(labName(),esc(t),o)}
function labelTick(){if(!S.lab||!ownsLabel())return;const L=S.lab;let inc=0;const staff=L.promo*[0,5000,15000,40000][L.promo]/Math.max(1,L.promo)||0;FX.m(-([0,5000,15000,40000][L.promo]));if(L.head)FX.m(-3000);
 L.roster.forEach(a=>{const s=a.single;if(s&&s.pts>0){s.w++;s.pts=curve(s.base,s.w);if(s.pts<1||s.w>30)s.pts=0;const i=s.pts*320*.6;inc+=i;a.fame=clamp(a.fame+s.pts/90,0,100)}
  if(a.tourLeft){a.tourLeft--;inc+=1500+a.fame*150;a.fame=clamp(a.fame+.6,0,100)}
  a.morale=clamp(a.morale-(L.head?0:1)-(s&&s.pts>0?0:.5),0,100);if(a.char)S.npcF[a.char]=Math.round(a.fame-npcFame(a.char)+(S.npcF[a.char]||0));
  if(a.morale<22&&!UI.queue.find(q=>q.id==='lab_unhappy'))UI.queue.push({id:'lab_unhappy',ev:unhappyEv(a)})});
 inc=Math.round(inc);FX.m(inc);L.earn+=inc;if(inc>0)log(`${labName()} earned ${money(inc)} from its artists.`,'good');L.rep=clamp(L.rep-.15,0,100)}
function unhappyEv(a){return{sys:1,id:'lab_unhappy',tag:labName(),who:a.char||null,title:`${a.name} wants out`,mood:'angry',text:`${a.name} feels ignored. "You care more about your own records than mine." They want to be released from their contract.`,ch:[c('Promise a single and a bigger budget','$25K, morale up',()=>{FX.m(-25000);a.morale=70;return 'They agreed to stay. For now.'}),c('Let them go','',()=>{S.lab.roster=S.lab.roster.filter(x=>x!==a);S.lab.rep-=4;if(a.char)FX.a(a.char,-10);news(`${a.name} leaves ${labName()}`,'bad');return 'They signed with Edgehill a week later.'}),c('Hold them to their contract','Morale crashes',()=>{a.morale=35;if(a.char)FX.a(a.char,-20);FX.heat(5);return 'Bitter, but still yours.'})]}}
VIEWS.label=function(){ensureLab();const L=S.lab;const own=ownsLabel();if(!own)return`<section class="card"><p class="muted">You don't own a label. Start one from Life › Business.</p></section>`;
 return`<section class="card labhead"><div class="between"><div><span class="eyebrow">Your record label</span><h2>${esc(labName())}</h2></div>${S.label.id==='own'?'<button class="mini ghosty" data-lab="rename">Rename</button>':''}</div>${meter('Label rep',L.rep,'gold')}<p class="small muted">Lifetime label earnings ${money(L.earn)} · ${L.roster.length} artists · You keep 60% of your artists' royalties.</p>
 <h3>Weekly promotion budget</h3><div class="seg">${['None','$5K','$15K','$40K'].map((n,i)=>`<button class="${L.promo===i?'on':''}" data-lab="promo" data-uid="${i}">${n}</button>`).join('')}</div><p class="small faint">More promo means your artists' singles and your own climb higher.</p>
 <div class="songrow"><div><b>Label president${L.head?': '+esc(fullnm(L.head)):''}</b><small>Keeps artists happy while you're on the road. $3K/week.</small></div><button class="mini ${L.head?'ghosty':''}" data-labhead="1">${L.head?'Let go':'Hire'}</button></div></section>
 <section class="card"><h3>Roster</h3>${L.roster.length?L.roster.map(a=>`<div class="act"><div class="act-pt">${portrait(a.look,{mood:a.morale>50?'happy':a.morale<30?'angry':'neutral'})}</div><div class="act-info"><b>${esc(a.name)}</b><small>Talent ${stars(a.talent)} · Fame ${Math.round(a.fame)}${a.hits?` · ${a.hits} hit${a.hits>1?'s':''}`:''}</small>${meter('Morale',a.morale,a.morale<30?'bad':'good')}<small>${a.single&&a.single.pts>0?`On radio: "${esc(a.single.title)}"${a.single.pos?' · #'+a.single.pos:''}`:a.tourLeft?`On tour, ${a.tourLeft} weeks left`:'Nothing out right now'}</small>
 <div class="act-btns"><button class="mini" data-lab="single" data-uid="${a.uid}">Fund a single</button><button class="mini ghosty" data-lab="meet" data-uid="${a.uid}">Check in</button>${a.tourLeft?'':`<button class="mini ghosty" data-lab="tour" data-uid="${a.uid}">Send on tour</button>`}${a.char?`<button class="mini ghosty" data-lab="duet" data-uid="${a.uid}">Duet with them</button>`:''}<button class="mini ghosty" data-lab="drop" data-uid="${a.uid}">Drop</button></div></div></div>`).join(''):'<p class="muted">No artists yet. Sign someone below.</p>'}</section>
 <section class="card"><div class="between"><h3>Scouting list</h3><button class="mini" data-lab="scout" data-uid="">Scout ⚡15</button></div>${L.prospects.map(a=>`<div class="act"><div class="act-pt">${portrait(a.look)}</div><div class="act-info"><b>${esc(a.name)}</b><small>${a.char?esc(CHARS[a.char].role)+' · ':'Unsigned act · '}Talent ${stars(a.talent)} · Fame ${Math.round(a.fame)}</small><small>Advance: ${money(a.ask)}</small><div class="act-btns"><button class="mini" data-lab="sign" data-uid="${a.uid}">Offer a deal</button></div></div></div>`).join('')}</section>`};

// ---------- tour planner ----------
const CITIES=['Atlanta','Dallas','Houston','Austin','Tulsa','Kansas City','Denver','Phoenix','Las Vegas','Los Angeles','Chicago','Detroit','Columbus','Charlotte','Raleigh','Birmingham','New Orleans','Memphis','Louisville','St. Louis','Minneapolis','Seattle','Boston','New York','Philadelphia','Knoxville','Lexington','Oklahoma City','San Antonio','Jacksonville','Indianapolis','Omaha','Salt Lake City','Toronto'];
window.startTour=function(tid){const t=TOURS.find(x=>x.id===tid);if(S.tour)return;if(fame()<t.fame)return toast('Not famous enough for this tour yet.');
 const P={price:1,prod:1,vip:0,merch:1,opener:''};const openers=Object.keys(CHARS).filter(k=>has(k)&&CHARS[k].singer&&npcFame(k)<fame()&&R(k).a>=5&&!(S.lab&&ownsLabel()&&S.lab.roster.some(x=>x.char===k))).concat((S.lab&&ownsLabel()?S.lab.roster:[]).map(a=>'lab:'+a.uid));
 const body=()=>{const pm=[.75,1,1.4][P.price],fm=[1.12,1,.85][P.price],cm=[.7,1,1.6][P.prod];const fill=clamp(S.fans*.009*fm*(.8+S.loyal/250)/t.cap,.08,1);const wk=Math.round(t.cap*fill*t.price*pm*3*.3+(P.merch?t.cap*fill*3*4:0)+(P.vip?t.cap*fill*3*5:0)-t.cost*cm);
  return`<h2>${esc(t.n)}</h2><p class="muted small">${t.weeks} weeks · ${num(t.cap)}-capacity rooms · 3 shows a week · ${esc(t.desc)}</p>
  <h3>Ticket prices</h3><div class="seg">${['Fan-friendly','Standard','Premium'].map((n,i)=>`<button class="${P.price===i?'on':''}" data-tp="price" data-v="${i}">${n}</button>`).join('')}</div><p class="small faint">${['Cheaper seats fill faster and fans love you for it.','A fair price.','More money per seat, emptier rooms and grumbling fans.'][P.price]}</p>
  <h3>Production</h3><div class="seg">${['Stripped','Standard','Spectacular'].map((n,i)=>`<button class="${P.prod===i?'on':''}" data-tp="prod" data-v="${i}">${n}</button>`).join('')}</div><p class="small faint">${['Just you and a band. Cheap, intimate.','Lights, screens, the works.','Pyro, a catwalk and a flying stage. Better shows, huge costs.'][P.prod]}</p>
  <h3>Extras</h3><div class="chips-sel"><button class="${P.merch?'on':''}" data-tp="merch">Merch stand</button><button class="${P.vip?'on':''}" data-tp="vip">VIP meet-and-greets</button></div>
  <h3>Opening act</h3><div class="chips-sel"><button class="${!P.opener?'on':''}" data-tp="opener" data-v="">Local openers</button>${openers.map(o=>{const n=o.startsWith('lab:')?S.lab.roster.find(a=>'lab:'+a.uid===o).name+' (your label)':fullnm(o);return`<button class="${P.opener===o?'on':''}" data-tp="opener" data-v="${o}">${esc(n)}</button>`}).join('')}</div>
  <div class="card inset"><b>Projected: ${Math.round(fill*100)}% full · about ${money(wk)} a week</b><small class="faint" style="display:block">${S.week-(S.flags.lastTour||-99)<26?'You toured recently, so some fans will wait for the next one. ':''}Up-front deposit ${money(t.cost)}${S.staff.manager?' · your manager takes 15%':''}</small></div>
  <div class="mfoot"><button class="ghost" data-x>Cancel</button><button class="primary" data-go>Announce the tour</button></div>`};
 modal(body(),{onClick:e=>{const tg=e.target;if(tg.closest('[data-x]'))return closeModal();const b=tg.closest('[data-tp]');if(b){const k=b.dataset.tp;if(k==='merch'||k==='vip')P[k]=P[k]?0:1;else if(k==='opener')P.opener=b.dataset.v;else P[k]=+b.dataset.v;$('#mbody').innerHTML=body();return}
  if(tg.closest('[data-go]')){if(S.money<t.cost)return toast('You need '+money(t.cost)+' up front for deposits.');FX.m(-t.cost);const route=shuffle(CITIES).slice(0,t.weeks-1).concat(['Nashville']);
   S.tour={n:t.n,id:t.id,left:t.weeks,weeks:t.weeks,cap:t.cap,price:t.price,cost:t.cost,gross:0,net:0,fans:0,route,pm:[.75,1,1.4][P.price],fm:[1.12,1,.85][P.price],cm:[.7,1,1.6][P.prod],perfB:[-4,0,8][P.prod],loyD:[1.2,0,-1.5][P.price],vip:P.vip,merch:P.merch,opener:P.opener};S.ap=Math.min(S.ap,apMax());S.stats.tours++;ach('tour');
   news(`${S.name} announces the ${t.n}: ${t.weeks} weeks, ending with a homecoming show in Nashville`);post('me',`TOUR. ${route.slice(0,4).join(', ')} and more. Tickets Friday!`);log(`Announced the ${t.n}.`,'big');closeModal();save();render()}}})};
window.tourWeek=function(){const T=S.tour;if(!T)return;const city=T.route?T.route[T.weeks-T.left]:pick(CITIES);let net,fansG,P=perfScore(null);
 if(T.flat){net=T.flat;fansG=T.fansPer*(P/70)}else{const fatigue=S.week-(S.flags.lastTour||-99)<26?.6:1;const fill=clamp(S.fans*.009*fatigue*(S.staff.manager?1.12:1)*(T.fm||1)*(.8+S.loyal/250)*(T.opener?1.06:1)/T.cap,.08,1),shows=3;const gross=T.cap*fill*T.price*(T.pm||1)*shows;const merch=T.merch?T.cap*fill*shows*4:0,vip=T.vip?T.cap*fill*shows*5:0;net=Math.round(gross*.3+merch+vip-T.cost*(T.cm||1));if(S.staff.manager)net=Math.round(net*.85);T.gross+=gross;fansG=T.cap*fill*shows*.09*(P/70);T.fill=fill;S.loyal=clamp(S.loyal+(T.loyD||0)+(T.vip?.8:0),0,100);if(T.vip)FX.st(2)
  if(T.opener){if(T.opener.startsWith('lab:')){const a=S.lab&&S.lab.roster.find(x=>'lab:'+x.uid===T.opener);if(a){a.fame=clamp(a.fame+1.2,0,100);a.morale=clamp(a.morale+3,0,100)}}else FX.a(T.opener,2)}}
 if(city==='Nashville'&&T.left===1){fansG*=1.5;S.loyal+=3}
 FX.m(net);FX.f(fansG);T.net+=net;T.fans+=fansG;FX.st(5);FX.hp(-3);FX.rep((P-62)/12);T.left--;
 log(`${T.n}, week ${T.weeks-T.left}: ${city}${city==='Nashville'?' (homecoming!)':''}. ${net>=0?'Made':'Lost'} ${money(Math.abs(net))}, +${num(fansG)} fans${T.fill?`, ${Math.round(T.fill*100)}% full`:''}.`,net>=0?'good':'bad');
 if(T.left<=0){news(`${S.name} wraps the ${T.n}${T.gross?', grossing '+money(T.gross):''}`,'big');log(`Tour over! ${money(T.net)} net, ${num(T.fans)} new fans.`,'big');if(T.head)FX.a(T.head,8);if(!T.flat)S.flags.lastTour=S.week;S.tour=null;FX.st(-10)}};
window.perfScore=function(mini){let base=skillAvg()*.75+rnd(-12,14)+(S.staff.band?7*(S.bandMorale??70)/70:0)-(S.health<40?10:0)-(S.stress>80?6:0)+((S.tour&&S.tour.perfB)||0);if(S.traits.includes('stagefright'))base-=14;if(S.add.dep>55)base-=10;return Math.round(clamp(mini==null?base:mini*.6+base*.4+4,0,100))};

// ---------- chart with label artists ----------
window.updateChart=function(){
 S.npcSongs.forEach(s=>{s.w++;s.pts=curve(s.base,s.w)});S.npcSongs=S.npcSongs.filter(s=>s.pts>5&&s.w<32&&(!s.id||has(s.id)||s.id===S.char));
 const n=ri(1,3);for(let i=0;i<n;i++)npcRelease();while(S.npcSongs.length<26)npcRelease();
 const all=S.npcSongs.map(s=>({t:s.title,a:s.artist,id:s.id,pts:s.pts*(s.id&&S.npcF[s.id]?1+S.npcF[s.id]/100:1),me:0,w:s.w}));
 charting().forEach(s=>all.push({t:s.title,a:S.name+(s.duet?' & '+nm(s.duet):''),id:'me',pts:s.pts,me:1,w:s.w,sid:s.id}));
 if(S.lab&&ownsLabel())S.lab.roster.forEach(a=>{if(a.single&&a.single.pts>0)all.push({t:a.single.title,a:a.name,id:'lab',pts:a.single.pts,lab:1,uid:a.uid,w:a.single.w})});
 all.sort((a,b)=>b.pts-a.pts);const prev={};(S.chart||[]).forEach((c,i)=>prev[c.t]=i+1);
 S.chart=all.slice(0,40).map((c,i)=>Object.assign(c,{last:prev[c.t]||0}));
 S.chart.forEach((c,i)=>{const pos=i+1;
  if(c.lab){const a=S.lab.roster.find(x=>x.uid===c.uid);if(!a)return;const s=a.single,old=s.peak||99;s.pos=pos;if(!s.peak||pos<s.peak)s.peak=pos;if(pos<=10&&old>10){a.hits++;S.lab.rep=clamp(S.lab.rep+5,0,100);FX.fl('labTop10');a.morale=clamp(a.morale+15,0,100);news(`${labName()}'s ${a.name} cracks the Top 10 with "${s.title}"`,'big');log(`Your artist ${a.name} has a Top 10 hit!`,'big')}if(pos===1&&old!==1){S.lab.rep=clamp(S.lab.rep+10,0,100);news(`${a.name} hits #1 for ${labName()}!`,'big');log(`${a.name} is #1! ${labName()} is on fire.`,'big');sfx('big')}return}
  if(!c.me)return;const s=S.songs.find(x=>x.id===c.sid);if(!s)return;const old=s.peak||99;if(!s.peak||pos<s.peak)s.peak=pos;s.pos=pos;
  if(pos===1&&old!==1){S.stats.ones++;S.labelRel=clamp((S.labelRel||50)+8,0,100);S.loyal=clamp(S.loyal+3,0,100);log(`"${s.title}" is the #1 song in country music!`,'big');news(`${S.name} hits #1 with "${s.title}"`,'big');sfx('big');ach('first1');if(S.stats.ones>=5)ach('five1');post('me','NUMBER ONE. I can\'t stop crying. Thank you!!');fanPost(`"${s.title}" at #1 is the best thing to happen this year`)}
  else if(pos<=10&&old>10){S.stats.top10++;S.labelRel=clamp((S.labelRel||50)+4,0,100);log(`"${s.title}" cracked the Top 10 at #${pos}.`,'good');ach('top10')}});
 S.songs.forEach(s=>{if(s.pts>0&&!S.chart.find(c=>c.sid===s.id))s.pos=0});
 if(S.lab)S.lab.roster.forEach(a=>{if(a.single&&!S.chart.find(c=>c.uid===a.uid))a.single.pos=0})};

// ---------- weekly hook ----------
(function(){const _ew=window.endWeek;window.endWeek=function(silent){_ew(silent);if(!S.story)storyInit('free');
 labelTick();
 // fans & loyalty
 S.loyal=clamp(S.loyal+(S.heat>50?-1.2:0)+(S.week-S.lastPost>8?-.6:0)+(55-S.loyal)*.01,0,100);FX.f(S.fans*((S.loyal-55)/55)*.004);
 S.followers=Math.round(S.followers+S.fans*.0015+(S.heat>40?S.followers*.003:0));
 // label relationship
 if(S.label&&!ownsLabel()&&S.label.id!=='indie'){if(S.heat>60)S.labelRel=clamp(S.labelRel-1.5,0,100);S.labelRel+=(50-S.labelRel)*.01;if(!silent&&S.labelRel<20&&!F('shelveWarn')&&S.label.id==='edgehill'){FX.fl('shelveWarn');UI.queue.push({id:'lab_shelve',ev:shelveEv()})}}
 if(S.staff.band)S.bandMorale=clamp(S.bandMorale-(S.tour?1.2:.3),0,100);
 if(!silent&&S.staff.band&&S.bandMorale<25&&!F('bandQuitW')){FX.fl('bandQuitW');UI.queue.push({id:'band_quit',ev:bandEv()})}
 if(!S.trend.length||chance(.3))S.trend.unshift(pick(['#MusicCity','#CountryRadio','#NewMusicFriday','#BluebirdCafe','#OpryNight','#'+S.handle]));S.trend=S.trend.slice(0,6);
 worldEvents(silent);
 if(!silent&&S.story&&S.story.on&&!S.story.done&&inSummer(S.week)){const s=seasonOf(S.week);S.story.ended=S.story.ended||{};if(s<=SEASONS&&!S.story.ended[s]){S.story.ended[s]=1;UI.queue.unshift({id:'season_end_'+s,ev:seasonEnd(s)})}}}})();
function shelveEv(){return{sys:1,tag:'Label',who:LABELS[S.label.id].boss&&has(LABELS[S.label.id].boss)?LABELS[S.label.id].boss:null,title:'Your label has gone cold',mood:'angry',text:'Your calls go to voicemail. Your single got bumped for a newer act. Word is the label is thinking about shelving your next record.',ch:[c('Show up at the office and fight for yourself','Label relationship up',()=>{S.labelRel+=20;FX.st(8);return 'You walked into the president\'s office unannounced and played him your best song on an acoustic. He listened.'}),c('Ask to be released','',()=>{S.label=null;S.labelRel=50;FX.cred(3);news(`${S.name} and their label part ways`);return 'They let you go. You\'re free, and on your own.'}),c('Keep your head down','',()=>'You wait. It\'s the worst part of this business.')]}}
function bandEv(){return{sys:1,tag:'The band',title:'Your band is fed up',mood:'angry',text:'Your drummer speaks for everyone: too many miles, not enough money, and you haven\'t said thank you in months. They\'re thinking of walking.',ch:[c('Pay everyone a $10K bonus','',()=>{FX.m(-10000);S.bandMorale=80;S.flags.bandQuitW=0;return 'Hugs all round. Your bass player bought a boat.'}),c('Take them out and really apologise','',()=>{S.bandMorale=60;S.flags.bandQuitW=0;return 'Barbecue, beer and honesty. It helped.'}),c('Replace them with session players','',()=>{S.bandMorale=55;FX.cred(-2);S.flags.bandQuitW=0;return 'The new guys are good. They\'re not family.'})]}}

// ---------- relationship circle ----------
function circleCard(){const mgr=S.manager&&has(S.manager)?S.manager:null,L=S.label&&!ownsLabel()&&S.label.id!=='indie',fam=familyIds(),boss=L&&LABELS[S.label.id].boss&&has(LABELS[S.label.id].boss)?LABELS[S.label.id].boss:null;
 const row=(ic,lab,v,cls,sub,btns)=>`<div class="circ"><div class="circ-ic">${ic}</div><div class="circ-main"><div class="between"><b>${lab}</b><small class="faint">${sub||''}</small></div>${meter('',v,cls)}<div class="circ-btns">${btns}</div></div></div>`;
 return`<section class="card"><h3>Your circle</h3>
 ${row('🤠',`Fans: ${esc(fanbase())}`,S.loyal,S.loyal<35?'bad':'love',`${num(S.fans)} fans · ${num(S.followers)} followers`,'<button class="mini ghosty" data-circ="mail">Answer fan mail</button><button class="mini ghosty" data-circ="popup">Pop-up show</button><button class="mini ghosty" data-circ="club">Fan club party $5K</button>')}
 ${L?row(boss?`<span class="circ-pt">${pt(boss)}</span>`:'🏢',`Label: ${esc(label().n)}`,S.labelRel,S.labelRel<30?'bad':'blue',S.labelRel>=70?'They love you':S.labelRel<30?'Cold':'Business as usual','<button class="mini ghosty" data-circ="labmeet">Meet the label</button><button class="mini ghosty" data-circ="labdemand">Demand more support</button>'):''}
 ${ownsLabel()?row('🏷',`Your label: ${esc(labName())}`,S.lab?S.lab.rep:40,'gold',`${S.lab?S.lab.roster.length:0} artists`,'<button class="mini ghosty" data-tab="label">Open the label</button>'):''}
 ${mgr?row(`<span class="circ-pt">${pt(mgr)}</span>`,`Manager: ${esc(fullnm(mgr))}`,(R(mgr).a+100)/2,'good','','<button class="mini ghosty" data-circ="mgr">Strategy session</button>'):row('🧑‍💼','No manager',0,'bad','Hire one in Life › Team','')}
 ${fam.length?row(`<span class="circ-pt">${pt(fam[0])}</span>`,'Family',(familyAvg()+100)/2,familyAvg()<0?'bad':'good',fam.map(nm).join(', '),'<button class="mini ghosty" data-circ="family">Family dinner</button>'):''}
 ${S.staff.band?row('🎸','Your band',S.bandMorale,S.bandMorale<35?'bad':'good','','<button class="mini ghosty" data-circ="jam">Jam session</button><button class="mini ghosty" data-circ="bonus">Bonus $5K</button>'):''}
 ${S.partner&&has(S.partner)?row(`<span class="circ-pt">${pt(S.partner)}</span>`,`${R(S.partner).married?'Married to':'Dating'} ${esc(fullnm(S.partner))}`,R(S.partner).r,'love','',`<button class="mini ghosty" data-person="${S.partner}">See them</button>`):''}</section>`}
function circleAct(k){if(!useAP(1))return;const o=snap();let t='';
 if(k==='mail'){S.loyal+=5;FX.st(-3);t=pick(['A letter from a soldier in Afghanistan who listens to you on night watch.','A girl in Ohio who learned guitar from your videos.','A widower who played your song at his wife\'s funeral.'])+' You answered every one by hand.'}
 if(k==='popup'){S.loyal+=7;FX.f(300+S.fans*.006);S.followers+=200;t='You announced a free show in a parking lot two hours ahead. Two thousand people showed up.'}
 if(k==='club'){if(S.money<5000){S.ap+=(UI.lastCost||1);return toast('Not enough money.')}FX.m(-5000);S.loyal+=11;S.followers+=400;t=`A party for ${fanbase()} at a barn outside town. You line-danced with a 90-year-old.`}
 if(k==='labmeet'){S.labelRel+=8;const b=LABELS[S.label.id].boss;if(b)FX.a(b,4);t='Lunch with the label team. You played them demos and remembered everyone\'s kids\' names.'}
 if(k==='labdemand'){if(S.labelRel>=60){S.promo+=2;S.labelRel-=4;t='They agreed: an extra radio push on your next single.'}else{S.labelRel-=10;t='"Maybe deliver a hit first." Ouch.'}}
 if(k==='mgr'){FX.a(S.manager,6);t=`${fullnm(S.manager)} spread a career plan on the table.`;queueEvent(pick(['opener_offer','boots','duet_offer','offer_dirt'].filter(x=>{const e=EVENTS.find(y=>y.id===x);return e&&safeWhen(e)}))||'boots')}
 if(k==='family'){familyIds().forEach(f=>FX.a(f,6));FX.st(-10);t='Sunday dinner. Somebody burnt the biscuits. Nobody talked about the music business.'}
 if(k==='jam'){S.bandMorale+=10;FX.sk('guitar',1);t='A loose jam in the rehearsal room until midnight. You wrote a riff.'}
 if(k==='bonus'){if(S.money<5000){S.ap+=(UI.lastCost||1);return toast('Not enough money.')}FX.m(-5000);S.bandMorale+=22;t='Envelopes on every amp after soundcheck.'}
 S.loyal=clamp(S.loyal,0,100);S.labelRel=clamp(S.labelRel,0,100);S.bandMorale=clamp(S.bandMorale,0,100);log(t);result('Your circle',esc(t),o)}

