(function(){const _p=window.post;window.post=function(who,t,likes){_p(who,t,likes);const p=S.feed[0];if(who==='me'){S.lastPost=S.week;p.comments=[0,1,2].map(()=>({h:pick(FAN_HANDLES),t:pick(S.heat>50?['ur so fake lol','delete this','still a fan no matter what ❤','the drama 🍿','we stand with you']:['QUEEN 👑','crying in the club rn','see you in Dallas!!!','this is why I love you','drop the album already','my mom loves you too','🤠🤠🤠'])}));const fr=Object.keys(S.rel).filter(k=>has(k)&&R(k).a>=40&&CHARS[k].singer);if(fr.length&&chance(.5))p.comments.push({h:'@'+CHARS[pick(fr)].n.replace(/[^A-Za-z]/g,''),t:pick(['Proud of you!','❤️','Call me later!','Love this'])})}else if(CHARS[who])p.canReply=1}})();
